function DreamAdventuresStoreTabToggleLeft:RefreshGridItemByIndex(gridView, index)
    local luaIndex = index + 1
    local cell = gridView:NewListViewItem("ToggleCellNode1")
    ---@type CommonTabToggleLeftCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Behaviours.CommonTabToggleLeftCell")
    local preList = self._productList[luaIndex - 1]
    local isUnLock = self:IsUnlockHelper(preList)
    scr:FreshBaseUI({
        text = shopName[luaIndex],
        lock = not isUnLock
    })
    scr:FreshSelectStatus(luaIndex == checkNumber(self._curSelectIndex))
    if luaIndex == checkNumber(self._curSelectIndex) then
        local preName = shopName[luaIndex - 1]
        Events.Broadcast(Constants.EventNames.DreamAdventuresStoreTabEvent, self._productList[luaIndex], isUnLock, preName)
    end
    scr:SetCallBack(function()
        self._curSelectIndex = luaIndex
        self:RefreshUI()
    end)
    return cell
end
